#!/usr/bin/env python3
"""Patch 106: after Final check, send the fields an admin checked back to the extractors. They confirm the admin is right, or disagree with a finding, a link and an SOP reference; the admin rules. Adds migration 036. Run from the repo root. Safe to run twice."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'backend/app/api/v1/routes/audit_challenges.py': '', 'backend/migrations/versions/036_audit_challenges.py': '', 'frontend/src/api/auditChallenges.ts': '', 'frontend/src/components/enh/AuditChallenges.tsx': ''}
MOD = {'backend/app/models/all_models.py': [('class SourceRound(Base):\n', 'class AuditChallenge(Base):\n    """An admin\'s checked field sent back to the extractor to review. The admin\'s verdict is copied here when it is sent and is never changed\n    by the extractor\'s reply: the extractor confirms it, or disagrees with a finding, an optional link and an optional SOP reference.\n    Only an admin ruling of "overturned" changes the audit itself."""\n    __tablename__ = "audit_challenges"\n\n    id = Column(String(36), primary_key=True, default=new_uuid)\n    audit_id = Column(String(36), ForeignKey("field_audits.id", ondelete="CASCADE"), nullable=False, unique=True, index=True)\n    source_id = Column(String(36), ForeignKey("sources.id", ondelete="CASCADE"), nullable=False, index=True)\n    record_id = Column(String(36), nullable=True)\n    field = Column(String(255), nullable=False)\n    extractor_id = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True, index=True)\n    sent_by = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True)\n    sent_at = Column(DateTime(timezone=True), default=now_utc, index=True)\n    sent_note = Column(Text, nullable=True)\n    # what the admin had decided when it was sent\n    admin_verdict = Column(String(10), nullable=False)\n    admin_truth = Column(Text, nullable=True)\n    admin_note = Column(Text, nullable=True)\n    extracted_value = Column(JSON, nullable=True)\n    # the extractor\'s view\n    stance = Column(String(10), nullable=True)                 # agree | disagree\n    finding = Column(Text, nullable=True)\n    evidence_url = Column(String(1000), nullable=True)\n    sop_ref = Column(String(300), nullable=True)\n    responded_by = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True)\n    responded_at = Column(DateTime(timezone=True), nullable=True)\n    # the admin\'s ruling on a disagreement\n    ruling = Column(String(12), nullable=True)                 # upheld | overturned\n    ruling_note = Column(Text, nullable=True)\n    ruled_by = Column(String(36), ForeignKey("users.id", ondelete="SET NULL"), nullable=True)\n    ruled_at = Column(DateTime(timezone=True), nullable=True)\n\n\nclass SourceRound(Base):\n')], 'backend/app/api/v1/routes/quality.py': [('    return br.engagement(db, user, srcs, sc)\n', '    return br.engagement(db, user, srcs, sc)\n\n\n# Checked fields sent back to extractors (/quality/audit-challenges/...). Included last so every helper above exists.\nfrom app.api.v1.routes.audit_challenges import router as _challenge_router  # noqa: E402\nrouter.include_router(_challenge_router)\n')], 'frontend/src/components/enh/FinalCheck.tsx': [("import { adminUploadApi } from '@/api/adminUpload'\n", "import { adminUploadApi } from '@/api/adminUpload'\nimport { AdminChallenges } from '@/components/enh/AuditChallenges'\n"), ('          {(res.unmatched_sources.length > 0 || res.notes.length > 0) && (\n', '          <AdminChallenges projectId={projectId || undefined} sourceId={sourceId || undefined} sourceIds={(res.sources ?? []).map((s: any) => s.source_id).filter(Boolean)} />\n\n          {(res.unmatched_sources.length > 0 || res.notes.length > 0) && (\n')], 'frontend/src/pages/SourceDetail.tsx': [("import { FeedbackPanel } from '@/components/enh/FeedbackPanel'\n", "import { FeedbackPanel } from '@/components/enh/FeedbackPanel'\nimport { SourceChallenges } from '@/components/enh/AuditChallenges'\n"), ('      <FeedbackPanel sourceId={source.id} refreshKey={source.updated_at}', '      <SourceChallenges sourceId={source.id} refreshKey={source.updated_at} />\n\n      <FeedbackPanel sourceId={source.id} refreshKey={source.updated_at}')]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t and not (new in old and new != old): continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        elif new in t: continue
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
